from dental_release.paths import expand as _release_expand
import json
from pathlib import Path
ROOT = Path(_release_expand('@DENTAL_INPUT_ROOT@/workspace'))
HERE = Path(__file__).resolve().parent
REG = {}

def ref(key, path, klass, needle=None, kind='independent_review'):
    snap = HERE / 'raw/source_snapshot' / path
    lines = snap.read_text().splitlines()
    line = next((i + 1 for (i, x) in enumerate(lines) if needle and needle in x), 1)
    REG[key] = {'key': key, 'path': path, 'line': line, 'review_class': klass, 'kind': kind}
