ROWS = []

def add(k, status, refs, metric, resolution, why, blocker, full_chain=False):
    ROWS.append({'k': f'K{k:02}', 'proposed_status': status, 'evidence_keys': refs.split(), 'main_number': metric, 'resolution': resolution.split(), 'rationale': why, 'remaining_requirement': blocker, 'claim_type': 'information_link', 'full_chain_reviewed': full_chain, 'uncertainty': 'See remaining requirements and reviewed scope; X43 estimates no new physical confidence intervals.'})
